parameters.command:
\
# Configure CRM Lookup connector node
uip maestro flow node configure BillingDisputeResolution.flow crmLookup1 \
  --detail "$(cat <<'JSON'
{
  "connectionId": "d61e5d0e-04af-4f93-95cc-151d81fa08dc",
  "folderKey": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
  "method": "POST",
  "endpoint": "/v3/QueryEntityRecords/query",
  "queryParameters": {
    "entityScope": "tenant",
    "tenantEntityName": "BillingDisputeCRM"
  },
  "bodyParameters": {
    "filterGroup": {
      "filter": [
        {
          "fieldName": "accountNumber",
          "operator": "Equal",
          "values": ["=js:$vars.start.output.webhookPayload.customer.accountNumber"]
        }
      ]
    }
  },
  "customFieldsRequestDetails": {
    "objectActionName": "FetchObjectMetadataTenant",
    "parameterValues": [
      ["tenantEntityName", "BillingDisputeCRM"]
    ]
  }
}
JSON
)" --output json 2>/dev/null | python3 -c "import sys,json; d=json.load(sys.stdin); print('CRM configure result:', d.get('Result'), d.get('Code'))"

\
# Configure ERP Lookup connector node
uip maestro flow node configure BillingDisputeResolution.flow erpLookup1 \
  --detail "$(cat <<'JSON'
{
  "connectionId": "d61e5d0e-04af-4f93-95cc-151d81fa08dc",
  "folderKey": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
  "method": "POST",
  "endpoint": "/v3/QueryEntityRecords/query",
  "queryParameters": {
    "entityScope": "tenant",
    "tenantEntityName": "BillingDisputeERP"
  },
  "bodyParameters": {
    "filterGroup": {
      "filter": [
        {
          "fieldName": "invoiceNumber",
          "operator": "Equal",
          "values": ["=js:$vars.normalizeData.output.normalizedInvoiceNumber"]
        }
      ]
    }
  },
  "customFieldsRequestDetails": {
    "objectActionName": "FetchObjectMetadataTenant",
    "parameterValues": [
      ["tenantEntityName", "BillingDisputeERP"]
    ]
  }
}
JSON
)" --output json 2>/dev/null | python3 -c "import sys,json; d=json.load(sys.stdin); print('ERP configure result:', d.get('Result'), d.get('Code'))"

